package netproxy

import (
	"context"
	"crypto/tls"
	"errors"
	"net"
)

// Dialer opens TLS connections along the path an https request would take. The
// zero value follows the proxy environment variables.
type Dialer struct {
	// Proxy picks the proxy; nil means FromEnvironment.
	Proxy Selector
	// DialContext opens the TCP connection (to the proxy, or to the target when
	// direct); nil means (&net.Dialer{}).DialContext.
	DialContext func(ctx context.Context, network, addr string) (net.Conn, error)
	// ProxyTLSConfig configures TLS to an https:// proxy; nil means system roots.
	ProxyTLSConfig *tls.Config
}

// DialTLS connects to hostport (the port is required) the way an https request
// to it would travel, then completes the handshake with cfg (ServerName
// defaults to the host). ctx bounds the whole: proxy dial, CONNECT, handshake.
// TODO(DEVDESK-585): stub, written in the green phase.
func (d Dialer) DialTLS(_ context.Context, _ string, _ *tls.Config) (*tls.Conn, error) {
	return nil, errors.New("netproxy: DialTLS not implemented")
}
package netproxy

// Step names the stage of the proxy path that failed.
type Step string

const (
	// StepSelect: the proxy setting is invalid.
	StepSelect Step = "select"
	// StepDial: the proxy cannot be reached.
	StepDial Step = "dial"
	// StepProxyTLS: TLS to an https:// proxy failed.
	StepProxyTLS Step = "proxy-tls"
	// StepConnect: CONNECT was refused, unreadable, or unanswered.
	StepConnect Step = "connect"
	// StepScheme: the proxy scheme is not supported (socks5).
	StepScheme Step = "scheme"
)

// Error is a failure at the proxy step of a connection, as opposed to a failure
// of the target itself. Proxy is host:port, never a userinfo.
type Error struct {
	// Proxy is the proxy's host:port.
	Proxy string
	// Step is where the proxy path failed.
	Step Step
	// StatusCode is the proxy's answer to CONNECT, 0 when it never gave one.
	StatusCode int
	// Err is the underlying cause, if any.
	Err error
}

// Error implements error. TODO(DEVDESK-585): stub, written in the green phase.
func (e *Error) Error() string { return "netproxy: error text not implemented" }

// Unwrap returns the underlying cause.
func (e *Error) Unwrap() error { return e.Err }
// Package netproxy decides which proxy a connection to a host travels through,
// the way an https request to that host would (DEVDESK-581), so that code which
// opens its own connections follows the same path as net/http.
package netproxy

import (
	"net/http"
	"net/url"
)

// Selector says which proxy carries a connection to u; nil, nil means direct.
// A nil Selector behaves like FromEnvironment.
type Selector func(u *url.URL) (*url.URL, error)

// FromEnvironment is http.ProxyFromEnvironment(&http.Request{URL: u}): the same
// function and the same once-per-process cache as the HTTPS monitor.
func FromEnvironment(u *url.URL) (*url.URL, error) {
	return http.ProxyFromEnvironment(&http.Request{URL: u})
}

// ForRequest adapts s to http.Transport.Proxy. A nil s falls back to
// FromEnvironment, so the zero value follows the proxy environment variables.
func (s Selector) ForRequest(r *http.Request) (*url.URL, error) {
	if s == nil {
		return FromEnvironment(r.URL)
	}
	return s(r.URL)
}

// NewTransport returns http.DefaultTransport.Clone() with Proxy = s.ForRequest,
// so timeouts and limits match the default transport. A nil s is equivalent to
// FromEnvironment.
func NewTransport(s Selector) *http.Transport {
	t := http.DefaultTransport.(*http.Transport).Clone()
	t.Proxy = s.ForRequest
	return t
}
package netproxy

import (
	"context"
	"errors"
	"testing"
)

func TestStepValues(t *testing.T) {
	tests := []struct {
		step Step
		want string
	}{
		{StepSelect, "select"},
		{StepDial, "dial"},
		{StepProxyTLS, "proxy-tls"},
		{StepConnect, "connect"},
		{StepScheme, "scheme"},
	}
	for _, tt := range tests {
		if string(tt.step) != tt.want {
			t.Errorf("step %q, want %q", tt.step, tt.want)
		}
	}
}

// TestErrorText pins the exact sentences the UI will show (Rule 129). In
// StepConnect, the status code decides "refused"; without one, a timeout cause
// is "no answer" and any other cause is "unreadable".
func TestErrorText(t *testing.T) {
	boom := errors.New("boom")
	tests := []struct {
		name string
		err  *Error
		want string
	}{
		{"refused 403", &Error{Proxy: "proxy.corp:3128", Step: StepConnect, StatusCode: 403},
			"proxy: CONNECT refused (403 Forbidden)"},
		{"refused 407", &Error{Proxy: "proxy.corp:3128", Step: StepConnect, StatusCode: 407},
			"proxy: CONNECT refused (407 Proxy Authentication Required)"},
		{"refused 502 with a cause", &Error{Proxy: "proxy.corp:3128", Step: StepConnect, StatusCode: 502, Err: boom},
			"proxy: CONNECT refused (502 Bad Gateway)"},
		{"no answer", &Error{Proxy: "proxy.corp:3128", Step: StepConnect, Err: context.DeadlineExceeded},
			"proxy: no answer from proxy.corp:3128 (timeout)"},
		{"unreadable", &Error{Proxy: "proxy.corp:3128", Step: StepConnect, Err: boom},
			"proxy: unreadable answer to CONNECT from proxy.corp:3128"},
		{"unreachable", &Error{Proxy: "proxy.corp:3128", Step: StepDial, Err: boom},
			"proxy: cannot reach proxy.corp:3128: boom"},
		{"proxy TLS", &Error{Proxy: "proxy.corp:3128", Step: StepProxyTLS, Err: boom},
			"proxy: TLS to proxy.corp:3128 failed: boom"},
		{"invalid setting", &Error{Step: StepSelect, Err: boom},
			"proxy: invalid proxy setting: boom"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.err.Error(); got != tt.want {
				t.Fatalf("Error() = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestErrorUnwrap(t *testing.T) {
	boom := errors.New("boom")
	var err error = &Error{Proxy: "proxy.corp:3128", Step: StepDial, Err: boom}
	if !errors.Is(err, boom) {
		t.Error("errors.Is does not reach the cause")
	}
	if got := (&Error{Step: StepConnect, StatusCode: 403}).Unwrap(); got != nil {
		t.Errorf("Unwrap() = %v, want nil without a cause", got)
	}
}
package netproxy

import (
	"bufio"
	"bytes"
	"context"
	"crypto/tls"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"time"
)

type Dialer struct {
	Proxy          Selector
	DialContext    func(ctx context.Context, network, addr string) (net.Conn, error)
	ProxyTLSConfig *tls.Config
}

type bufConn struct {
	net.Conn
	r io.Reader
}

func (c *bufConn) Read(p []byte) (int, error) { return c.r.Read(p) }

func (d Dialer) DialTLS(ctx context.Context, hostport string, cfg *tls.Config) (*tls.Conn, error) {
	host, _, err := net.SplitHostPort(hostport)
	if err != nil {
		return nil, err
	}
	sel := d.Proxy
	if sel == nil {
		sel = FromEnvironment
	}
	pu, err := sel(&url.URL{Scheme: "https", Host: hostport})
	if err != nil {
		return nil, &Error{Step: StepSelect, Err: err}
	}
	dial := d.DialContext
	if dial == nil {
		dial = (&net.Dialer{}).DialContext
	}
	var conn net.Conn
	if pu == nil {
		conn, err = dial(ctx, "tcp", hostport)
		if err != nil {
			return nil, err
		}
	} else {
		if pu.Scheme != "http" && pu.Scheme != "https" {
			return nil, &Error{Proxy: pu.Host, Step: StepScheme, Err: errors.New(pu.Scheme)}
		}
		conn, err = d.connect(ctx, dial, pu, hostport)
		if err != nil {
			return nil, err
		}
	}
	stop := context.AfterFunc(ctx, func() { _ = conn.Close() })
	defer stop()
	if dl, ok := ctx.Deadline(); ok {
		_ = conn.SetDeadline(dl)
	}
	var c *tls.Config
	if cfg != nil {
		c = cfg.Clone()
	} else {
		c = &tls.Config{}
	}
	if c.ServerName == "" {
		c.ServerName = host
	}
	tc := tls.Client(conn, c)
	if err := tc.HandshakeContext(ctx); err != nil {
		_ = conn.Close()
		return nil, err
	}
	_ = conn.SetDeadline(zeroTime)
	return tc, nil
}

func (d Dialer) connect(ctx context.Context, dial func(context.Context, string, string) (net.Conn, error), pu *url.URL, hostport string) (net.Conn, error) {
	addr := pu.Host
	if pu.Port() == "" {
		p := "80"
		if pu.Scheme == "https" {
			p = "443"
		}
		addr = net.JoinHostPort(pu.Hostname(), p)
	}
	conn, err := dial(ctx, "tcp", addr)
	if err != nil {
		return nil, &Error{Proxy: pu.Host, Step: StepDial, Err: err}
	}
	stop := context.AfterFunc(ctx, func() { _ = conn.Close() })
	defer stop()
	if dl, ok := ctx.Deadline(); ok {
		_ = conn.SetDeadline(dl)
	}
	fail := func(e *Error) (net.Conn, error) { _ = conn.Close(); return nil, e }
	if pu.Scheme == "https" {
		cfg := &tls.Config{}
		if d.ProxyTLSConfig != nil {
			cfg = d.ProxyTLSConfig.Clone()
		}
		if cfg.ServerName == "" {
			cfg.ServerName = pu.Hostname()
		}
		tc := tls.Client(conn, cfg)
		if err := tc.HandshakeContext(ctx); err != nil {
			return fail(&Error{Proxy: pu.Host, Step: StepProxyTLS, Err: err})
		}
		conn = tc
	}
	req := fmt.Sprintf("CONNECT %s HTTP/1.1\r\nHost: %s\r\n", hostport, hostport)
	if pu.User != nil {
		pw, _ := pu.User.Password()
		req += "Proxy-Authorization: Basic " + base64.StdEncoding.EncodeToString([]byte(pu.User.Username()+":"+pw)) + "\r\n"
	}
	if _, err := io.WriteString(conn, req+"\r\n"); err != nil {
		return fail(&Error{Proxy: pu.Host, Step: StepConnect, Err: err})
	}
	br := bufio.NewReader(io.LimitReader(conn, 64<<10))
	resp, err := http.ReadResponse(br, &http.Request{Method: http.MethodConnect})
	if err != nil {
		return fail(&Error{Proxy: pu.Host, Step: StepConnect, Err: err})
	}
	if resp.StatusCode != 200 {
		return fail(&Error{Proxy: pu.Host, Step: StepConnect, StatusCode: resp.StatusCode})
	}
	if br.Buffered() > 0 {
		b, _ := br.Peek(br.Buffered())
		conn = &bufConn{Conn: conn, r: io.MultiReader(bytesReader(b), conn)}
	}
	return conn, nil
}

var zeroTime time.Time

func bytesReader(b []byte) io.Reader { return bytes.NewReader(append([]byte(nil), b...)) }
package netproxy

import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/http"
)

// Step names the stage of the proxy path that failed.
type Step string

const (
	// StepSelect: the proxy setting is invalid.
	StepSelect Step = "select"
	// StepDial: the proxy cannot be reached.
	StepDial Step = "dial"
	// StepProxyTLS: TLS to an https:// proxy failed.
	StepProxyTLS Step = "proxy-tls"
	// StepConnect: CONNECT was refused, unreadable, or unanswered.
	StepConnect Step = "connect"
	// StepScheme: the proxy scheme is not supported (socks5).
	StepScheme Step = "scheme"
)

// Error is a failure at the proxy step of a connection, as opposed to a failure
// of the target itself. Proxy is host:port, never a userinfo.
type Error struct {
	// Proxy is the proxy's host:port.
	Proxy string
	// Step is where the proxy path failed.
	Step Step
	// StatusCode is the proxy's answer to CONNECT, 0 when it never gave one.
	StatusCode int
	// Err is the underlying cause, if any.
	Err error
}

// Error implements error. TODO(DEVDESK-585): stub, written in the green phase.
func (e *Error) Error() string {
	switch e.Step {
	case StepSelect:
		return "proxy: invalid proxy setting: " + e.Err.Error()
	case StepScheme:
		return "proxy: scheme " + e.Err.Error() + " is not supported by the SSL check"
	case StepDial:
		return "proxy: cannot reach " + e.Proxy + ": " + e.Err.Error()
	case StepProxyTLS:
		return "proxy: TLS to " + e.Proxy + " failed: " + e.Err.Error()
	}
	if e.StatusCode != 0 {
		return fmt.Sprintf("proxy: CONNECT refused (%d %s)", e.StatusCode, http.StatusText(e.StatusCode))
	}
	var ne net.Error
	if errors.Is(e.Err, context.DeadlineExceeded) || (errors.As(e.Err, &ne) && ne.Timeout()) {
		return "proxy: no answer from " + e.Proxy + " (timeout)"
	}
	return "proxy: unreadable answer to CONNECT from " + e.Proxy
}

// Unwrap returns the underlying cause.
func (e *Error) Unwrap() error { return e.Err }

package netproxy

import (
	"bufio"
	"context"
	"crypto/tls"
	"crypto/x509"
	"encoding/base64"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/http/httptest"
	"net/url"
	"reflect"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/anthnel/devdesk/internal/testutil/connectproxy"
	"github.com/anthnel/devdesk/internal/testutil/loopback"
)

// trackedConn remembers whether it was closed.
type trackedConn struct {
	net.Conn
	closed atomic.Bool
}

func (c *trackedConn) Close() error {
	c.closed.Store(true)
	return c.Conn.Close()
}

// tracker is a Dialer.DialContext that records every address asked for and
// every connection it opened.
type tracker struct {
	mu    sync.Mutex
	addrs []string
	conns []*trackedConn
}

func (tr *tracker) DialContext(ctx context.Context, network, addr string) (net.Conn, error) {
	tr.mu.Lock()
	tr.addrs = append(tr.addrs, addr)
	tr.mu.Unlock()
	c, err := (&net.Dialer{}).DialContext(ctx, network, addr)
	if err != nil {
		return nil, err
	}
	tc := &trackedConn{Conn: c}
	tr.mu.Lock()
	tr.conns = append(tr.conns, tc)
	tr.mu.Unlock()
	return tc, nil
}

func (tr *tracker) dialed() []string {
	tr.mu.Lock()
	defer tr.mu.Unlock()
	return append([]string(nil), tr.addrs...)
}

func (tr *tracker) opened() []*trackedConn {
	tr.mu.Lock()
	defer tr.mu.Unlock()
	return append([]*trackedConn(nil), tr.conns...)
}

// trusting is a client config that trusts only srv's certificate.
func trusting(srv *httptest.Server) *tls.Config {
	pool := x509.NewCertPool()
	pool.AddCert(srv.Certificate())
	return &tls.Config{RootCAs: pool}
}

func testCtx(t *testing.T, d time.Duration) context.Context {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), d)
	t.Cleanup(cancel)
	return ctx
}

// dialTLS runs DialTLS and closes the connection when the test ends.
func dialTLS(t *testing.T, ctx context.Context, d Dialer, hostport string, cfg *tls.Config) (*tls.Conn, error) {
	t.Helper()
	conn, err := d.DialTLS(ctx, hostport, cfg)
	if conn != nil {
		t.Cleanup(func() { _ = conn.Close() })
	}
	return conn, err
}

// proxyError asserts err is a *Error and returns it.
func proxyError(t *testing.T, err error) *Error {
	t.Helper()
	var pe *Error
	if !errors.As(err, &pe) {
		t.Fatalf("error = %T %v, want a *netproxy.Error", err, err)
	}
	return pe
}

// reservedProxyURL is the URL of a proxy nobody listens on: connecting to a
// reserved port is refused at once (DEVDESK-35).
func reservedProxyURL(t *testing.T) *url.URL {
	t.Helper()
	return mustURL(t, "http://"+net.JoinHostPort("127.0.0.1", strconv.Itoa(loopback.ReservePort(t))))
}

// rawProxy is a proxy that reads one request per connection and lets answer
// write whatever bytes it wants, for answers connectproxy refuses to produce.
func rawProxy(t *testing.T, answer func(conn net.Conn)) *url.URL {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	var (
		mu    sync.Mutex
		conns []net.Conn
		wg    sync.WaitGroup
		done  = make(chan struct{})
	)
	go func() {
		defer close(done)
		for {
			c, err := ln.Accept()
			if err != nil {
				return
			}
			mu.Lock()
			conns = append(conns, c)
			mu.Unlock()
			wg.Add(1)
			go func() {
				defer wg.Done()
				defer func() { _ = c.Close() }()
				if _, err := http.ReadRequest(bufio.NewReader(c)); err != nil {
					return
				}
				answer(c)
			}()
		}
	}()
	t.Cleanup(func() {
		_ = ln.Close()
		<-done
		mu.Lock()
		for _, c := range conns {
			_ = c.Close()
		}
		mu.Unlock()
		wg.Wait()
	})
	return mustURL(t, "http://"+ln.Addr().String())
}

// peerChain is the raw certificate chain the peer presented.
func peerChain(certs []*x509.Certificate) [][]byte {
	var chain [][]byte
	for _, c := range certs {
		chain = append(chain, c.Raw)
	}
	return chain
}

func TestDialTLSThroughAProxyPresentsTheSameChainAsHTTPS(t *testing.T) {
	srv := newTLSServer(t)
	proxy := connectproxy.Start(t, connectproxy.Options{
		Route: func(string) string { return srv.Listener.Addr().String() },
	})
	d := Dialer{Proxy: fixed(proxy.URL())}

	conn, err := dialTLS(t, testCtx(t, 10*time.Second), d, "example.com:443", trusting(srv))
	if err != nil {
		t.Fatalf("DialTLS: %v", err)
	}
	state := conn.ConnectionState()
	if !state.HandshakeComplete {
		t.Fatal("the handshake is not complete")
	}
	if state.ServerName != "example.com" {
		t.Fatalf("ServerName = %q, want the host of the target", state.ServerName)
	}
	want := []connectproxy.Request{{Target: "example.com:443"}}
	if got := proxy.Requests(); !reflect.DeepEqual(got, want) {
		t.Fatalf("proxy received %+v, want exactly %+v", got, want)
	}

	// The same target fetched by net/http, through the same proxy.
	resp, _ := httpsGet(t, NewTransport(fixed(proxy.URL())), srv, "https://example.com/")
	got, wantChain := peerChain(state.PeerCertificates), peerChain(resp.TLS.PeerCertificates)
	if len(got) == 0 || !reflect.DeepEqual(got, wantChain) {
		t.Fatalf("DialTLS chain (%d certificates) differs from the HTTPS monitor's (%d)", len(got), len(wantChain))
	}
}

func TestDialTLSKeepsAnExplicitServerName(t *testing.T) {
	srv := newTLSServer(t)
	proxy := connectproxy.Start(t, connectproxy.Options{
		Route: func(string) string { return srv.Listener.Addr().String() },
	})
	cfg := trusting(srv)
	cfg.ServerName = "example.com"
	// The target host is not in the certificate; the explicit name is.
	conn, err := dialTLS(t, testCtx(t, 10*time.Second), Dialer{Proxy: fixed(proxy.URL())}, "other.test:443", cfg)
	if err != nil {
		t.Fatalf("DialTLS: %v", err)
	}
	if got := conn.ConnectionState().ServerName; got != "example.com" {
		t.Fatalf("ServerName = %q, want %q", got, "example.com")
	}
}

func TestDialTLSNilSelectorFollowsTheEnvironment(t *testing.T) {
	srv := newTLSServer(t)
	var tr tracker
	// A loopback address is never proxied, whatever the environment says.
	target := srv.Listener.Addr().String()
	conn, err := dialTLS(t, testCtx(t, 10*time.Second), Dialer{DialContext: tr.DialContext}, target, trusting(srv))
	if err != nil {
		t.Fatalf("DialTLS: %v", err)
	}
	if !conn.ConnectionState().HandshakeComplete {
		t.Fatal("the handshake is not complete")
	}
	if got := tr.dialed(); !reflect.DeepEqual(got, []string{target}) {
		t.Fatalf("dialed %v, want only the target %s", got, target)
	}
}

func TestDialTLSDirectSelectorDialsTheTarget(t *testing.T) {
	srv := newTLSServer(t)
	proxy := connectproxy.Start(t, connectproxy.Options{})
	var tr tracker
	real := srv.Listener.Addr().String()
	d := Dialer{
		Proxy: direct,
		// example.com is a name in the httptest certificate; route it to the server.
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			if addr == "example.com:443" {
				addr = real
			}
			return tr.DialContext(ctx, network, addr)
		},
	}
	if _, err := dialTLS(t, testCtx(t, 10*time.Second), d, "example.com:443", trusting(srv)); err != nil {
		t.Fatalf("DialTLS: %v", err)
	}
	if got := tr.dialed(); !reflect.DeepEqual(got, []string{real}) {
		t.Fatalf("dialed %v, want the target only", got)
	}
	if got := proxy.Requests(); len(got) != 0 {
		t.Fatalf("a direct connection reached the proxy: %+v", got)
	}
}

func TestDialTLSAsksTheSelectorAboutAnHTTPSURL(t *testing.T) {
	srv := newTLSServer(t)
	var seen *url.URL
	sel := func(u *url.URL) (*url.URL, error) { seen = u; return nil, nil }
	real := srv.Listener.Addr().String()
	d := Dialer{Proxy: sel, DialContext: func(ctx context.Context, network, _ string) (net.Conn, error) {
		return (&net.Dialer{}).DialContext(ctx, network, real)
	}}
	if _, err := dialTLS(t, testCtx(t, 10*time.Second), d, "example.com:443", trusting(srv)); err != nil {
		t.Fatalf("DialTLS: %v", err)
	}
	if seen == nil || seen.Scheme != "https" || seen.Host != "example.com:443" {
		t.Fatalf("selector saw %v, want https://example.com:443", seen)
	}
}

func TestDialTLSRefusesAHostWithoutAPort(t *testing.T) {
	var tr tracker
	if _, err := dialTLS(t, testCtx(t, 10*time.Second), Dialer{Proxy: direct, DialContext: tr.DialContext}, "example.com", nil); err == nil {
		t.Fatal("DialTLS accepted a host without a port")
	}
	if got := tr.dialed(); len(got) != 0 {
		t.Fatalf("dialed %v for an invalid address", got)
	}
}

func TestDialTLSProxyRefusal(t *testing.T) {
	tests := []struct {
		name string
		code int
		want string
	}{
		{"forbidden", http.StatusForbidden, "proxy: CONNECT refused (403 Forbidden)"},
		{"proxy authentication required", http.StatusProxyAuthRequired, "proxy: CONNECT refused (407 Proxy Authentication Required)"},
		{"bad gateway", http.StatusBadGateway, "proxy: CONNECT refused (502 Bad Gateway)"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			proxy := connectproxy.Start(t, connectproxy.Options{Refuse: tt.code})
			var tr tracker
			d := Dialer{Proxy: fixed(proxy.URL()), DialContext: tr.DialContext}
			conn, err := dialTLS(t, testCtx(t, 10*time.Second), d, "example.com:443", nil)
			if conn != nil || err == nil {
				t.Fatalf("DialTLS = %v, %v; want an error and no connection", conn, err)
			}
			pe := proxyError(t, err)
			if pe.Step != StepConnect || pe.StatusCode != tt.code {
				t.Fatalf("Step, StatusCode = %q, %d; want %q, %d", pe.Step, pe.StatusCode, StepConnect, tt.code)
			}
			if pe.Proxy != proxy.URL().Host {
				t.Fatalf("Proxy = %q, want %q", pe.Proxy, proxy.URL().Host)
			}
			if err.Error() != tt.want {
